    __shared__ float shB[BLOCK_SIZE][BLOCK_SIZE];

    float sum = 0.0f;

    // Iterate over tiles
    int numTiles = (N + BLOCK_SIZE - 1) / BLOCK_SIZE;
    for (int t = 0; t < numTiles; ++t) {
        // Load tiles into shared memory
        // Current thread's position within the tile
        int tidX = threadIdx.x;
        int tidY = threadIdx.y;

        // Global index for loading A
        int aRow = row;
        int aCol = t * BLOCK_SIZE + tidX;
        if (aRow < N && aCol < N) {
            shA[tidY][tidX] = A[aRow * N + aCol];
        } else {
            shA[tidY][tidX] = 0.0f; // Pad with zeros if out of bounds
